import copy


def merge(base: dict, override: dict) -> dict:
    """Return a new dict that is a deep merge of *base* and *override*.

    - Nested dicts are merged recursively.
    - Lists and scalars from *override* REPLACE the base value; lists are
      never concatenated.
    - A key whose value in *override* is ``None`` is REMOVED from the
      result, even when the key is absent from *base*.
    - Neither input is modified; the result shares no mutable objects
      with either input.

    Raises:
        ValueError: if *base* or *override* is not a dict.
    """
    if not isinstance(base, dict):
        raise ValueError("base must be a dict, got %r" % type(base).__name__)
    if not isinstance(override, dict):
        raise ValueError("override must be a dict, got %r" % type(override).__name__)

    result = {}
    for key, value in base.items():
        result[key] = copy.deepcopy(value)

    for key, value in override.items():
        if value is None:
            result.pop(key, None)
        elif isinstance(value, dict) and isinstance(result.get(key), dict):
            result[key] = merge(result[key], value)
        else:
            result[key] = copy.deepcopy(value)

    return result
